def fitness_function(tree, X, y):
    y_pred = safe_evaluate(tree, X)
    mse = float(np.mean((y - y_pred) ** 2))
    tree_size = tree.size()
    if tree_size > X.shape[0] * 2:
        mse += 0.1 * np.log10(tree_size)
    return mse


def selection(population, fitnesses, n_select, tournament_size=7):
    selected = []
    pop_size = len(population)
    if len(fitnesses) >= 2:
        safe_min, safe_max = min(fitnesses), max(fitnesses)
        factor = safe_max / (safe_min + 1e-10) if safe_max > safe_min else 1.0
        fitnesses = [math.exp(f / factor) for f in fitnesses]
        fitnesses = [(f - min(fitnesses)) / (max(fitnesses) - min(fitnesses) + 1e-10)
                    for f in fitnesses]
    for _ in range(n_select):
        candidates = random.sample(range(pop_size), min(tournament_size, pop_size))
        best = min(candidates, key=lambda i: fitnesses[i])
        selected.append(population[best].copy())
    return selected


def crossover(parent1, parent2, n_features, max_depth=17):
    offspring = parent1.copy()
    donor = parent2.copy()
    terminals = []
    def find_terminals(node, loc):
        if node.is_terminal:
            terminals.append((loc[0], loc[1]))
        else:
            for i, child in enumerate(node.children):
                find_terminals(child, (loc[0], i))
    find_terminals(offspring, (0, 0))
    if not terminals or donor.size() <= 1:
        return offspring
    loc_idx = random.randint(0, len(terminals) - 1)
    node_loc = terminals[loc_idx]
    donor_nodes = donor.get_all_nodes()
    don_node_idx = random.randint(1, donor.size() - 1)
    donor_subtree = donor_nodes[don_node_idx][0].copy()
    off_nodes = offspring.get_all_nodes()
    off_node = off_nodes[node_loc[0]]
    parent = off_node[1]
    child_idx = node_loc[1]
    if parent is not None:
        parent.children[child_idx] = donor_subtree
    if offspring.depth() > max_depth:
        return offspring
    return offspring


def mutation(parent, n_features, max_depth=17):
    offspring = parent.copy()
    tree_size = offspring.size()
    if tree_size < 2:
        offspring = generate_tree('grow', 3, n_features)
        if offspring.depth() > max_depth:
            return parent.copy()
        return offspring
    shift_factor = 0.3
    def pick_subtree(root, min_size=1):
        candidates = []
        def count_nodes(node):
            if node.is_terminal:
                return 1
            return 1 + sum(count_nodes(c) for c in node.children)
        fifo = [(root, root.size())]
        while fifo:
            node, s = fifo.pop()
            if s >= min_size and node.is_terminal:
                candidates.append(node.copy())
            if s >= min_size:
                candidates.append(node.copy())
            for i, child in enumerate(node.children):
                fifo.append((child, count_nodes(child)))
        if not candidates:
            return generate_tree('grow', 3, n_features)
        return random.choice(candidates)
    r = random.random()
    if r < shift_factor:
        nodes = offspring.get_all_nodes()
        nonterminal_idx = random.randint(1, tree_size - 1)
        node, par_node, child_idx = nodes[nonterminal_idx]
        if r2 := random.random() < 0.67 and len(node.children) >= 1:
            new_subtree = pick_subtree(node, min_size=1)
            if par_node is not None:
                par_node.children[child_idx] = new_subtree
            else:
                offspring = new_subtree
        else:
            new_op = random.choice(OPERATOR_NAMES)
            _, arity = OPERATORS[new_op]
            if len(node.children) >= arity:
                for i in range(arity):
                    node.value = new_op
                nodes = offspring.get_all_nodes()
                node, par_node, child_idx = nodes[nonterminal_idx]
                if par_node is not None:
                    par_node.children[child_idx] = node
                offspring = node
    else:
        mutations_threshold = max(1, tree_size // 2) - 1
        mut_point = random.randint(1, tree_size - 1)
        new_subtree = pick_subtree(offspring, min_size=mutations_threshold)
        nodes = offspring.get_all_nodes()
        node, par, child_idx = nodes[mut_point]
        if par:
            par.children[child_idx] = new_subtree
        else:
            offspring = new_subtree
    if offspring.depth() > max_depth:
        if tree_size > 10:
            return pick_subtree(offspring, min_size=5).copy()
        return offspring
    return offspring


def evolve_one_generation(population, fitnesses, X_train, y_train,
                          n_features, pop_size,
                          crossover_rate=0.9, mutation_rate=0.05,
                          max_depth=17):
    new_population = []
    elite_idx = int(np.argmin(fitnesses))
    new_population.append(population[elite_idx].copy())
    sizes = np.array([tree.size() for tree in population])
    variance = float(np.var(sizes))
    adaptive_mut_rate = max(0.01, mutation_rate * (2 + 2 * variance / 100))
    for _ in range(pop_size - 1):
        parents = selection(population, fitnesses, 2)
        r = random.random()
        if r < crossover_rate:
            child = crossover(parents[0], parents[1], n_features, max_depth)
        elif r < crossover_rate + adaptive_mut_rate:
            parents = selection(population, fitnesses, 1)
            child = mutation(parents[0], n_features, max_depth)
        else:
            parents = selection(population, fitnesses, 1)
            child = parents[0]
        new_population.append(child)
    return new_population[:pop_size]

